css:
@page { size: 4in 2in; margin: 0; }
.print-format { padding: 0 !important; margin: 0 !important; max-width: 4in !important; }
.bb-label { width: 3.85in; height: 1.85in; border: 1.5px solid #000; border-radius: 6px; padding: 5px 7px; box-sizing: border-box;
  font-family: Arial, Helvetica, sans-serif; color: #000; position: relative; overflow: hidden; }
.bb-label .hosp { font-size: 9pt; font-weight: bold; text-transform: uppercase; white-space: nowrap; overflow: hidden; width: 2.6in; }
.bb-label .grp { position: absolute; right: 6px; top: 5px; border: 2.5px solid #000; border-radius: 6px; width: 0.95in; text-align: center;
  font-weight: 900; line-height: 1; padding: 3px 0; }
.bb-label .grp .abo { font-size: 30pt; display: block; }
.bb-label .grp .rh { font-size: 11pt; display: block; letter-spacing: 1px; }
.bb-label .bc svg { height: 0.42in; width: auto; max-width: 2.6in; display: block; margin-top: 3px; }
.bb-label .unit { font-size: 12pt; font-weight: bold; letter-spacing: 1px; }
.bb-label .comp { font-size: 11pt; font-weight: bold; margin-top: 2px; }
.bb-label .row { font-size: 8.5pt; margin-top: 1px; }
.bb-label .exp { font-size: 10pt; font-weight: bold; }
.bb-label .foot { font-size: 7.5pt; position: absolute; bottom: 4px; left: 7px; right: 7px; border-top: 1px solid #000; padding-top: 2px; }
